(()=>{const files=[{"name": "SOURCE_MANIFEST.json", "b64": ""}, {"name": "main.tex", "b64": ""}];const transfer=new DataTransfer();for(const f of files){transfer.items.add(new File([Uint8Array.from(atob(f.b64),c=>c.charCodeAt(0))],f.name,{type:'application/octet-stream'}));}const input=document.querySelector('input[type=file]:not([webkitdirectory])');if(!input)return 'Upload dialog missing';input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));return JSON.stringify({selected:files.map(f=>f.name)});})()